  {id:"p6302w2cu", sem:"s2", course:"PHAR6302", week:"Week 2", title:"Week 2 Weekly Check Up &mdash; hypertension", note:"University, ungraded. 8 questions, verbatim. Answers checked against HF 2016.", from:_N_FROM, count:8},
  {id:"p6302f62", sem:"s2", course:"PHAR6302", week:"Week 2", title:"Figure 6.2 questions &mdash; drug treatment", note:"University questions. 3 questions, verbatim, with the university&rsquo;s feedback.", from:_N_FROM+8, count:3},
  {id:"p6302w3cu", sem:"s2", course:"PHAR6302", week:"Week 3", title:"Week 3 Weekly Check Up &mdash; lipids &amp; diabetes", note:"University, ungraded. 10 questions, verbatim, with the university&rsquo;s feedback.", from:_N_FROM+11, count:10}
